#D - Divide Interval
def divide_interval():
    l, r = map(int, input().split())

    lis = []
    while l < r:
        i = 0
        while l % pow(2, i+1) == 0 and l + pow(2, i+1) <= r:
            i += 1
        lis.append([l, l + pow(2, i)])
        l += pow(2, i)

    print(len(lis))
    for interval in lis:
        print(*interval)
